{"command":"cat << 'EOF' > nomino.py
#!/usr/bin/env python3
import sys
import os
import re
import json
from pathlib import Path
from collections import OrderedDict

def print_help():
    print("""Batch rename utility for developers

Usage: executable [OPTIONS] [[SOURCE] OUTPUT]...

Arguments:
  [[SOURCE] OUTPUT]...  OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option

Options:
  -d, --dir <PATH>         Sets the working directory
      --depth <DEPTH>      Optional value to overwrite inferred subdirectory depth value in 'regex' mode
  -E, --no-extension       Does not preserve the extension of input files in 'sort' and 'regex' options
  -g, --generate <PATH>    Stores a JSON map file in '<PATH>' after renaming files
  -h, --help               Print help (see more with '--help')
  -k, --mkdir              Recursively creates all parent directories of '<OUTPUT>' if they are missing
  -m, --map <PATH>         Sets the path of map file to be used for renaming files [aliases: --from-file]
      --max-depth <DEPTH>  Optional value to set the maximum of subdirectory depth value in 'regex' mode
  -q, --quiet              Does not print the map table to stdout
  -r, --regex <PATTERN>    Regex pattern to match by filenames
  -s, --sort <ORDER>       Sets the order of natural sorting (by name) to rename files using enumerator [possible values: asc, desc]
  -t, --test               Runs in test mode without renaming actual files [aliases: --dry-run]
  -V, --version            Print version
  -w, --overwrite          Overwrites output files, otherwise, a '_' is prepended to filename

OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.""")

def parse_args():
    args = sys.argv[1:]
    if '--help' in args or '-h' in args:
        print_help()
        sys.exit(0)
    if '--version' in args or '-V' in args:
        print("nomino 1.6.4")
        sys.exit(0)

    options = {
        'dir': '.', 'depth': None, 'no_extension': False, 'generate': None,
        'mkdir': False, 'map': None, 'max_depth': None, 'quiet': False,
        'regex': None, 'sort': None, 'test': False, 'overwrite': False
    }
    positionals = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-d', '--dir'):
            options['dir'] = args[i+1]
            i += 1
        elif arg == '--depth':
            options['depth'] = int(args[i+1])
            i += 1
        elif arg in ('-E', '--no-extension'):
            options['no_extension'] = True
        elif arg in ('-g', '--generate'):
            options['generate'] = args[i+1]
            i += 1
        elif arg in ('-k', '--mkdir'):
            options['mkdir'] = True
        elif arg in ('-m', '--map', '--from-file'):
            options['map'] = args[i+1]
            i += 1
        elif arg == '--max-depth':
            options['max_depth'] = int(args[i+1])
            i += 1
        elif arg in ('-q', '--quiet'):
            options['quiet'] = True
        elif arg in ('-r', '--regex'):
            options['regex'] = args[i+1]
            i += 1
        elif arg in ('-s', '--sort'):
            val = args[i+1]
            if val not in ('asc', 'desc'):
                print(f"error: invalid value '{val}' for '--sort <ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.")
                sys.exit(2)
            options['sort'] = val
            i += 1
        elif arg in ('-t', '--test', '--dry-run'):
            options['test'] = True
        elif arg in ('-w', '--overwrite'):
            options['overwrite'] = True
        elif arg.startswith('-'):
            print(f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: executable [OPTIONS] [[SOURCE] OUTPUT]...\n\nFor more information, try '--help'.")
            sys.exit(2)
        else:
            positionals.append(arg)
        i += 1

    if not any(options[k] for k in ['regex', 'sort', 'map']) and len(positionals) < 2:
        if len(positionals) == 1 and not options['regex'] and not options['sort'] and not options['map']:
            print("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run './executable --help' for more information.")
            sys.exit(1)
        elif len(positionals) == 0 and not any(options[k] for k in ['regex', 'sort', 'map']):
            print("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run './executable --help' for more information.")
            sys.exit(1)

    output = None
    if len(positionals) == 2:
        options['regex'] = positionals[0]
        output = positionals[1]
    elif len(positionals) == 1:
        output = positionals[0]

    return options, output

def natural_sort_key(s):
    return [int(text) if text.isdigit() else text.lower() for text in re.split(r'(\d+)', s)]

def walk_dir(directory, min_depth, max_depth):
    # WalkDir order (top-down)
    paths = []
    base = Path(directory)
    for root, dirs, files in os.walk(directory):
        # We need paths relative to directory
        root_path = Path(root)
        try:
            rel_root = root_path.relative_to(base)
        except ValueError:
            continue
        depth = len(rel_root.parts) + 1 if str(rel_root) != '.' else 1

        # Sort files and dirs alphabetically to ensure deterministic order similar to WalkDir
        dirs.sort()
        files.sort()

        for name in files + dirs:
            p = rel_root / name
            d = depth
            if (min_depth is None or d >= min_depth) and (max_depth is None or d <= max_depth):
                paths.append(str(p))
    return paths

def parse_template(template):
    parts = []
    auto_idx = 1
    pos = 0
    pattern = re.compile(r'\{([a-zA-Z0-9_]*)(?::(\d+))?\}')
    for m in pattern.finditer(template):
        parts.append(('text', template[pos:m.start()]))
        g = m.group(1)
        p = m.group(2)
        if not g:
            g = str(auto_idx)
            auto_idx += 1
        parts.append(('var', g, p))
        pos = m.end()
    parts.append(('text', template[pos:]))
    return parts

def evaluate_template(parts, groups):
    res = ""
    for t in parts:
        if t[0] == 'text':
            res += t[1]
        else:
            g = t[1]
            p = t[2]
            val = ""
            if g.isdigit():
                idx = int(g)
                if idx < len(groups):
                    val = groups[idx]
            elif g in groups: # Named groups not implemented for simplicity, or we can use dict
                val = groups[g]
            if p and val.lstrip('-').isdigit():
                val = val.zfill(int(p)) if not val.startswith('-') else '-' + val[1:].zfill(int(p))
            res += val
    return res

def prepend_underscore(path_str):
    p = Path(path_str)
    return str(p.with_name('_' + p.name))

def main():
    try:
        options, output = parse_args()
    except SystemExit as e:
        sys.exit(e.code)

    base_dir = options['dir']

    # Process mode
    ops = OrderedDict() # output -> input

    if options['map']:
        try:
            with open(options['map'], 'r') as f:
                mapping = json.load(f, object_pairs_hook=OrderedDict)
        except Exception as e:
            print(f"error: No such file or directory (os error 2)" if isinstance(e, FileNotFoundError) else f"error: {e}")
            sys.exit(1)
        for k, v in mapping.items():
            out_path = v
            if not options['overwrite']:
                while os.path.exists(os.path.join(base_dir, out_path)):
                    out_path = prepend_underscore(out_path)
            ops[out_path] = k

    else:
        if options['regex']:
            min_depth = options['depth']
            if min_depth is None:
                min_depth = options['regex'].count('/') + 1
            max_depth = options['max_depth']
            if max_depth is None:
                max_depth = min_depth

            try:
                rx = re.compile(options['regex'])
            except Exception as e:
                print(f"error: regex parse error:\n    {options['regex']}\n    ^\nerror: {e}")
                sys.exit(1)

            paths = walk_dir(base_dir, min_depth, max_depth)
            template_parts = parse_template(output) if output else []

            for p in paths:
                m = rx.search(Path(p).name)
                if m:
                    groups = [m.group(i) or "" for i in range(m.lastindex + 1 if m.lastindex else 1)]
                    if not groups: groups = [m.group(0)]
                    out_name = evaluate_template(template_parts, groups)
                    if not options['no_extension']:
                        ext = Path(p).suffix
                        if ext and not out_name.endswith(ext):
                            out_name += ext

                    out_path = str(Path(p).with_name(out_name))
                    if out_path == p:
                        ops[out_path] = p
                        continue

                    if not options['overwrite']:
                        while os.path.exists(os.path.join(base_dir, out_path)):
                            out_path = prepend_underscore(out_path)
                    ops[out_path] = p

        elif options['sort']:
            paths = walk_dir(base_dir, 1, 1) # Default depth 1 for sort
            paths.sort(key=lambda x: natural_sort_key(Path(x).name), reverse=(options['sort'] == 'desc'))
            template_parts = parse_template(output) if output else []

            enumerator = 1
            for p in paths:
                groups = [Path(p).name, str(enumerator)]
                out_name = evaluate_template(template_parts, groups)
                if not options['no_extension']:
                    ext = Path(p).suffix
                    if ext and not out_name.endswith(ext):
                        out_name += ext

                out_path = str(Path(p).with_name(out_name))
                if out_path == p:
                    ops[out_path] = p
                    enumerator += 1
                    continue

                if not options['overwrite']:
                    while os.path.exists(os.path.join(base_dir, out_path)):
                        out_path = prepend_underscore(out_path)
                ops[out_path] = p
                enumerator += 1

    successes = []

    for out, inp in ops.items():
        if options['test']:
            successes.append((inp, out))
            continue

        if inp == out:
            successes.append((inp, out))
            continue

        src = os.path.join(base_dir, inp)
        dst = os.path.join(base_dir, out)

        if options['mkdir']:
            os.makedirs(os.path.dirname(dst), exist_ok=True)

        try:
            os.rename(src, dst)
            successes.append((inp, out))
        except OSError as e:
            # Emulate rust error format
            print(f"[error] unable to rename '{inp}': {e.strerror} (os error {e.errno})")

    if successes:
        successes.sort(key=lambda x: x[1])

        if options['generate']:
            gen_map = OrderedDict()
            for inp, out in successes:
